void retained_public_categorical_cases() {
  std::size_t matched = 0;
  for (const auto& fixture : categorical_cases()) {
    const auto before = serialize_oc_playout_workbench_ocel_json(fixture.input);
    const auto result = filter_ocel_event_attribute_exact(
        fixture.input,fixture.key,fixture.values,fixture.positive,fixture.column_kind);
    const bool equal = serialize_oc_playout_workbench_ocel_json(result) ==
        serialize_oc_playout_workbench_ocel_json(fixture.expected) &&
        serialize_oc_playout_workbench_ocel_json(fixture.input) == before;
    if (!equal) std::cerr << "categorical mismatch: " << fixture.name << '\n';
    matched += equal;
  }
  std::cout << matched << "/" << categorical_cases().size() << " categorical public outcomes" << std::endl;
  assert(matched == categorical_cases().size());
}
void retained_public_timestamp_cases() {
  std::size_t matched = 0;
  for (const auto& fixture : timestamp_cases()) {
    const auto before = serialize_oc_playout_workbench_ocel_json(fixture.input);
    const auto result = filter_ocel_events_timestamp_exact(
        fixture.input,fixture.lower,fixture.upper,fixture.key);
    const bool equal = serialize_oc_playout_workbench_ocel_json(result) ==
        serialize_oc_playout_workbench_ocel_json(fixture.expected) &&
        serialize_oc_playout_workbench_ocel_json(fixture.input) == before;
    if (!equal) std::cerr << "timestamp mismatch: " << fixture.name << '\n';
    matched += equal;
  }
  std::cout << matched << "/" << timestamp_cases().size() << " timestamp public outcomes" << std::endl;
  assert(matched == timestamp_cases().size());
}

