void full_native_state() {
  Ocel source;
  const auto raw = bytes("00ffeda080");
  source.events = {{"e1", "A", "2026-01-01T00:00:00.000000001Z",
                    {{raw, std::numeric_limits<double>::quiet_NaN()}, {"dup", nullptr}, {"dup", raw}}},
                   {"e0", "A", "2026-01-01T00:00:00Z", {{raw, true}}}};
  source.objects = {{raw, raw, {{raw, true}}}, {"other", "U", {}}};
  source.relations = {{"e0", raw, "q"}, {"e1", raw, raw},
                      {"e1", raw, "qualified duplicate"}, {"e1", "other", "q"}};
  source.o2o = {{raw, "other", "link"}, {raw, raw, raw}, {raw, raw, raw}};
  source.e2e = {{"e0", "e1", "link"}, {"e1", "e1", raw}};
  source.object_changes = {{raw, raw, "later", raw, raw},
                           {"other", "U", "later", "value", -0.0}};
  source.globals = {{raw, raw}, {"bool", true}, {"integer", std::int64_t{-7}}};
  source.event_type_attributes = {{"unused", {{raw, "string"}}}};
  source.object_type_attributes = {{raw, {{"ignored", "integer"}}}};
  source.table_columns.events = std::vector<std::string>{raw, "dup", "dup"};
  source.table_columns.objects = std::vector<std::string>{};
  source.table_columns.relations = std::nullopt;
  const auto before = serialize_oc_playout_workbench_ocel_json(source);
  auto expected = source;
  expected.events.pop_back();
  expected.relations.erase(expected.relations.begin());
  expected.e2e.erase(expected.e2e.begin());
  const auto expected_json = serialize_oc_playout_workbench_ocel_json(expected);
  auto result = filter_ocel_event_attribute_exact(source,raw,
      {std::numeric_limits<double>::quiet_NaN()});
  assert(serialize_oc_playout_workbench_ocel_json(result) == expected_json);
  const auto instant = datetime("2026-01-01T00:00:00.000000001Z");
  assert(serialize_oc_playout_workbench_ocel_json(
      filter_ocel_event_attribute_exact(source,"ocel:timestamp",{instant})) == expected_json);
  assert(filter_ocel_event_attribute_exact(source,"ocel:timestamp",
      {std::string("2026-01-01T00:00:00.000000001Z")}).events.empty());
  assert(serialize_oc_playout_workbench_ocel_json(
      filter_ocel_events_timestamp_exact(source,instant,instant)) == expected_json);
  result.globals[raw] = std::string("independent");
  result.events[0].attributes.clear();
  assert(serialize_oc_playout_workbench_ocel_json(source) == before);
  auto dated = source;
  for (auto& event : dated.events) {
    event.attributes.push_back({"date", event.timestamp});
    event.attributes.push_back({"literal date", event.timestamp});
  }
  dated.event_type_attributes["A"]["date"] = "time";
  dated.event_type_attributes["A"]["literal date"] = "string";
  dated.table_columns.events->push_back("date");
  dated.table_columns.events->push_back("literal date");
  auto dated_expected = expected;
  dated_expected.events[0].attributes.push_back({"date", dated_expected.events[0].timestamp});
  dated_expected.events[0].attributes.push_back({"literal date", dated_expected.events[0].timestamp});
  dated_expected.event_type_attributes = dated.event_type_attributes;
  dated_expected.table_columns = dated.table_columns;
  const auto dated_json = serialize_oc_playout_workbench_ocel_json(dated_expected);
  assert(serialize_oc_playout_workbench_ocel_json(
      filter_ocel_event_attribute_exact(dated,"date",{instant})) == dated_json);
  assert(filter_ocel_event_attribute_exact(dated,"literal date",{instant}).events.empty());
  assert(serialize_oc_playout_workbench_ocel_json(filter_ocel_event_attribute_exact(
      dated,"literal date",{instant},true,OcelEventAttributeColumnKind::kTimestamp)) == dated_json);
  assert(serialize_oc_playout_workbench_ocel_json(filter_ocel_event_attribute_exact(
      dated,"date",{std::string("2026-01-01T00:00:00.000000001Z")},true,
      OcelEventAttributeColumnKind::kScalar)) == dated_json);
}
